import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome20 {
    data class Success(val payload: String) : Outcome20()
    data object Failure : Outcome20()
}

fun describe20(outcome: Outcome20): String = when (outcome) {
    is Outcome20.Success -> outcome.payload
    Outcome20.Failure -> "failed"
}
fun <T> List<T>.secondOrNull21(): T? = if (size > 1) this[1] else null

fun render21(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
class Counter22 {
    var current: Int by Delegates.observable(45) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
